use crate::domain::enums::{CertificateLifecycle,ReleaseExecutionStatus};
#[derive(Clone,Debug,Eq,PartialEq)] pub enum TransitionError { Structural,Reference,Integrity,Temporal,Scope,Authority,IllegalTransition }
pub struct TransitionContext { pub structural:bool,pub reference:bool,pub integrity:bool,pub temporal:bool,pub scope:bool,pub authority:bool }
pub fn certificate_transition(source:CertificateLifecycle,target:CertificateLifecycle,context:&TransitionContext)->Result<(),TransitionError>{ if !context.structural||!context.reference||!context.integrity||!context.temporal||!context.scope||!context.authority{return Err(TransitionError::Authority)}; match(source,target){(CertificateLifecycle::Draft,CertificateLifecycle::Issued)|(CertificateLifecycle::Draft,CertificateLifecycle::Cancelled)|(CertificateLifecycle::Issued,CertificateLifecycle::Revoked)|(CertificateLifecycle::Issued,CertificateLifecycle::Superseded)|(CertificateLifecycle::Issued,CertificateLifecycle::Expired)=>Ok(()),_=>Err(TransitionError::IllegalTransition)} }
pub fn execution_transition(source:ReleaseExecutionStatus,target:ReleaseExecutionStatus,context:&TransitionContext)->Result<(),TransitionError>{ if !context.structural||!context.reference||!context.integrity||!context.temporal||!context.scope||!context.authority{return Err(TransitionError::Authority)}; match(source,target){(ReleaseExecutionStatus::NotStarted,ReleaseExecutionStatus::Started)|(ReleaseExecutionStatus::Started,ReleaseExecutionStatus::Succeeded)|(ReleaseExecutionStatus::Started,ReleaseExecutionStatus::Failed)|(ReleaseExecutionStatus::Started,ReleaseExecutionStatus::Cancelled)|(ReleaseExecutionStatus::Failed,ReleaseExecutionStatus::RolledBack)|(ReleaseExecutionStatus::Succeeded,ReleaseExecutionStatus::RolledBack)=>Ok(()),_=>Err(TransitionError::IllegalTransition)} }
